  "steps": [
    {
      "id": 1,
      "claim": "Dualism is a theory in public international law that treats international law and domestic (municipal) law as separate legal orders.",
      "evidence": "Standard definitions in international law textbooks (e.g., Shaw, International Law, 8th ed.; Crawford, Brownlie's Treaties).",
      "weight": 0.35,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Under dualism, international law has no direct effect in the domestic legal system unless it is incorporated by legislation (the transformation doctrine).",
      "evidence": "Dualist doctrine of transformation; case law such as R v Secretary of State for the Home Department, ex parte Simms (UK) and the practice of many dualist states.",
      "weight": 0.30,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Consequently, domestic law governs the internal legal order unless and until an international norm is transformed into domestic law; this does not imply that domestic law always prevails, only that the two systems are distinct and domestic law applies in the absence of transformation.",
      "evidence": "Scholarly analysis (e.g., Malcolm N. Shaw, International Law, 8th ed., ch. 5) clarifying that dualism allows international obligations to bind a state internationally even if they are not yet domestically enforceable.",
      "weight": 0.20,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Option B ('Under dualism, international and domestic laws comprise distinct legal systems') accurately captures the core dualist principle described in steps 1‑3.",
      "evidence": "Direct correspondence between the wording of option B and the definition and consequences outlined in steps 1‑3.",
      "weight": 0.10,
      "depends_on": [1, 2, 3]
    },
    {
      "id": 5,
      "claim": "Options A, C, and D each contain statements inconsistent with dualism: A describes monism (a unified system); C adds an equal hierarchical relationship not required by dualism; D asserts domestic law always prevails, which overstates the dualist position.",
      "evidence": "Comparative analysis of monist vs. dualist doctrines in standard literature.",
      "weight": 0.05,
      "depends_on": [1, 2, 3]
    }
  ],
  "answer": "B",
  "confidence": 0.96,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Describes monism, which posits a unified legal system, contrary to dualist separation."
    },
    {
      "answer": "C",
      "reason_rejected": "Introduces the notion of equal hierarchy, which is not a defining feature of dualism."
    },
    {
      "answer": "D",
      "reason_rejected": "Claims domestic law always prevails; dualism only gives domestic law primacy in the absence of transformation, not an absolute rule."
    }
  ]
}
